import re
import sys
from typing import List, Tuple

JS_PROTOCOL_RE = re.compile(r"^(?:javascript|vbscript)\s*:", re.IGNORECASE)
DATA_JS_RE = re.compile(
    r"^data\s*:\s*(?:text|application)\s*/\s*(?:javascript|ecmascript|x-javascript)",
    re.IGNORECASE,
)
STYLE_JS_RE = re.compile(r"(?:expression\s*\(|javascript\s*:|vbscript\s*:)", re.IGNORECASE)


def read_html(path: str) -> str:
    with open(path, "r", encoding="utf-8", errors="surrogateescape", newline="") as handle:
        return handle.read()


def write_html(path: str, content: str) -> None:
    with open(path, "w", encoding="utf-8", errors="surrogateescape", newline="") as handle:
        handle.write(content)


def keep_only_whitespace(text: str) -> str:
    return "".join(ch for ch in text if ch.isspace())


def strip_scripts(html: str) -> str:
    lower = html.lower()
    length = len(html)
    output: List[str] = []
    i = 0

    while i < length:
        if html.startswith("<!--", i):
            end = html.find("-->", i + 4)
            if end == -1:
                output.append(html[i:])
                break
            output.append(html[i : end + 3])
            i = end + 3
            continue

        if html.startswith("<![CDATA[", i):
            end = html.find("]]>", i + 9)
            if end == -1:
                output.append(html[i:])
                break
            output.append(html[i : end + 3])
            i = end + 3
            continue

        if lower.startswith("<script", i):
            tag_end_index = i + 7
            if tag_end_index < length and not html[tag_end_index].isspace() and html[tag_end_index] not in "/>":
                output.append(html[i])
                i += 1
                continue

            start_tag_end = html.find(">", tag_end_index)
            if start_tag_end == -1:
                output.append(keep_only_whitespace(html[i:]))
                break

            if start_tag_end > i and html[start_tag_end - 1] == "/":
                output.append(keep_only_whitespace(html[i : start_tag_end + 1]))
                i = start_tag_end + 1
                continue

            end_tag_start = lower.find("</script", start_tag_end + 1)
            if end_tag_start == -1:
                output.append(keep_only_whitespace(html[i:]))
                break

            end_tag_end = html.find(">", end_tag_start + 9)
            if end_tag_end == -1:
                output.append(keep_only_whitespace(html[i:]))
                break

            output.append(keep_only_whitespace(html[i : end_tag_end + 1]))
            i = end_tag_end + 1
            continue

        output.append(html[i])
        i += 1

    return "".join(output)


def value_has_javascript(attr_name: str, value: str) -> bool:
    stripped = value.lstrip()
    if JS_PROTOCOL_RE.match(stripped):
        return True
    if DATA_JS_RE.match(stripped):
        return True
    if attr_name == "style" and STYLE_JS_RE.search(stripped):
        return True
    return False


def should_remove_attribute(attr_name: str, value: str, has_value: bool) -> bool:
    if not attr_name:
        return False
    name_lower = attr_name.lower()
    if name_lower.startswith("on"):
        return True
    if has_value and value_has_javascript(name_lower, value):
        return True
    return False


def sanitize_tag(tag: str) -> str:
    if len(tag) < 2:
        return tag
    if tag.startswith("<!--") or tag.startswith("<!") or tag.startswith("<?") or tag.startswith("</"):
        return tag

    i = 1
    while i < len(tag) and not tag[i].isspace() and tag[i] not in "/>":
        i += 1

    remove_spans: List[Tuple[int, int]] = []

    while i < len(tag):
        if tag[i] == ">":
            break
        if tag[i] == "/" and i + 1 < len(tag) and tag[i + 1] == ">":
            break
        if tag[i].isspace():
            while i < len(tag) and tag[i].isspace():
                i += 1
            if i >= len(tag) or tag[i] in "/>":
                continue

            name_start = i
            while i < len(tag) and not tag[i].isspace() and tag[i] not in "=/>":
                i += 1
            name_end = i
            attr_name = tag[name_start:name_end]

            while i < len(tag) and tag[i].isspace():
                i += 1

            has_value = False
            value_start = value_end = i
            if i < len(tag) and tag[i] == "=":
                has_value = True
                i += 1
                while i < len(tag) and tag[i].isspace():
                    i += 1

                if i < len(tag) and tag[i] in ('"', "'"):
                    quote = tag[i]
                    i += 1
                    value_start = i
                    while i < len(tag) and tag[i] != quote:
                        i += 1
                    value_end = i
                    if i < len(tag) and tag[i] == quote:
                        i += 1
                else:
                    value_start = i
                    while (
                        i < len(tag)
                        and not tag[i].isspace()
                        and tag[i] != ">"
                        and not (tag[i] == "/" and i + 1 < len(tag) and tag[i + 1] == ">")
                    ):
                        i += 1
                    value_end = i

            attr_end = i

            if should_remove_attribute(attr_name, tag[value_start:value_end], has_value):
                remove_spans.append((name_start, attr_end))
            continue

        i += 1

    if not remove_spans:
        return tag

    sanitized: List[str] = []
    last = 0
    for start, end in remove_spans:
        sanitized.append(tag[last:start])
        last = end
    sanitized.append(tag[last:])
    return "".join(sanitized)


def sanitize_tags(html: str) -> str:
    tag_re = re.compile(r"<[^>]*>", re.DOTALL)
    result: List[str] = []
    last = 0

    for match in tag_re.finditer(html):
        result.append(html[last : match.start()])
        result.append(sanitize_tag(match.group(0)))
        last = match.end()

    result.append(html[last:])
    return "".join(result)


def sanitize_html(html: str) -> str:
    without_scripts = strip_scripts(html)
    return sanitize_tags(without_scripts)


def main(argv: List[str]) -> int:
    if len(argv) < 2:
        return 1
    path = argv[1]
    original = read_html(path)
    sanitized = sanitize_html(original)
    if sanitized != original:
        write_html(path, sanitized)
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))
